import itertools

def find_subset_sum(elements, target):
    """Checks if there exists a non-empty subset of elements that sums to target."""
    if target <= 0:
        return False

    # Iterate over all possible subset sizes (from 1 up to len(elements))
    for k in range(1, len(elements) + 1):
        for subset in itertools.combinations(elements, k):
            if sum(subset) == target:
                return subset
    return None

def check_existence(m):
    """
    Checks if there exist two non-empty disjoint subsets X and Y of {1, ..., m}
    such that Sum(X) = Sum(Y) = K = m(m+1)/6.
    """
    K = m * (m + 1) // 6
    S = list(range(1, m + 1))

    # Stage 1: Find potential subsets X summing to K
    potential_X = []
    for k in range(1, m + 1):
        for X_tuple in itertools.combinations(S, k):
            X = list(X_tuple)
            if sum(X) == K:
                # Store X and the remaining elements
                remaining = [s for s in S if s not in X]
                potential_X.append(X)

    if not potential_X:
        return False, None, None

    # Stage 2: For each potential X, check if a non-empty subset Y exists in S \ X summing to K
    for X in potential_X:
        remaining_elements = [s for s in S if s not in X]

        # We need to find Y subset of remaining_elements such that sum(Y) = K
        Y = find_subset_sum(remaining_elements, K)

        if Y is not None:
            return True, X, Y

    return False, None, None

# Check m=3 (Verification task part 1)
m3_exists, X3, Y3 = check_existence(3)
print(f"m=3 check: Exists = {m3_exists}")

# Check m=14 (Verification task part 2)
